//! Checks the blob format against `docs/test-vectors/blob-v1.json`, which was
//! generated by an independent Python implementation (`generate_blob_v1.py`).

use std::io::Cursor;

use ourstick_core::cipher::{AEAD_KEY_CONTEXT, NONCE_KEY_CONTEXT};
use ourstick_core::{
    decrypt_blob, encrypt_blob, ChaChaCipher, Cipher, NoCipher, StickKey, BLOB_FORMAT_VERSION,
    CHUNK_SIZE,
};
use serde::Deserialize;

const VECTORS: &str = include_str!("../../../docs/test-vectors/blob-v1.json");

#[derive(Deserialize)]
struct Document {
    blob_format_version: u8,
    chunk_size: usize,
    aead_key_context: String,
    nonce_key_context: String,
    vectors: Vec<Vector>,
}

/// One vector. Hex fields are lowercase hex strings. The key, nonce and
/// intermediate fields are only present for the XChaCha20-Poly1305 cipher.
#[derive(Deserialize)]
struct Vector {
    name: String,
    cipher: String,
    stick_key: Option<String>,
    plaintext: PlaintextSpec,
    plaintext_len: u64,
    aead_key: Option<String>,
    nonce_key: Option<String>,
    plaintext_hash: Option<String>,
    nonce_prefix: Option<String>,
    first_chunk_nonce: Option<String>,
    last_chunk_nonce: Option<String>,
    header: String,
    blob_len: u64,
    blob_hash: String,
    /// Only present when the blob is at most 1024 bytes.
    blob: Option<String>,
}

#[derive(Deserialize)]
#[serde(untagged)]
enum PlaintextSpec {
    Hex {
        hex: String,
    },
    /// `pattern_length` bytes where byte `i` is `i % 251`.
    Pattern {
        pattern_length: usize,
    },
}

fn document() -> Document {
    serde_json::from_str(VECTORS).expect("blob-v1.json is valid")
}

fn hex(text: &str) -> Vec<u8> {
    data_encoding::HEXLOWER.decode(text.as_bytes()).unwrap()
}

/// Decodes an optional hex field that `vector` must have.
fn required_hex(vector: &Vector, field: &Option<String>) -> Vec<u8> {
    let text = field
        .as_deref()
        .unwrap_or_else(|| panic!("vector {} is missing a field", vector.name));
    hex(text)
}

impl Vector {
    fn plaintext(&self) -> Vec<u8> {
        match &self.plaintext {
            PlaintextSpec::Hex { hex: text } => hex(text),
            PlaintextSpec::Pattern { pattern_length } => {
                (0..*pattern_length).map(|i| (i % 251) as u8).collect()
            }
        }
    }

    fn stick_key(&self) -> [u8; 32] {
        required_hex(self, &self.stick_key).try_into().unwrap()
    }

    fn cipher(&self) -> Box<dyn Cipher> {
        match self.cipher.as_str() {
            "none" => Box::new(NoCipher),
            "xchacha20-poly1305" => {
                Box::new(ChaChaCipher::new(&StickKey::from_bytes(self.stick_key())))
            }
            other => panic!("unknown cipher {other}"),
        }
    }
}

#[test]
fn vector_constants_match_implementation() {
    let document = document();
    assert_eq!(document.blob_format_version, BLOB_FORMAT_VERSION);
    assert_eq!(document.chunk_size, CHUNK_SIZE);
    assert_eq!(document.aead_key_context, AEAD_KEY_CONTEXT);
    assert_eq!(document.nonce_key_context, NONCE_KEY_CONTEXT);
}

#[test]
fn all_vectors_are_parsed() {
    assert_eq!(document().vectors.len(), 7);
}

#[test]
fn derived_keys_and_nonces_match_vectors() {
    for vector in document().vectors {
        if vector.cipher != "xchacha20-poly1305" {
            continue;
        }
        let name = &vector.name;
        let stick_key = vector.stick_key();
        let plaintext = vector.plaintext();

        let aead_key = blake3::derive_key(AEAD_KEY_CONTEXT, &stick_key);
        let nonce_key = blake3::derive_key(NONCE_KEY_CONTEXT, &stick_key);
        assert_eq!(
            aead_key.to_vec(),
            required_hex(&vector, &vector.aead_key),
            "{name}"
        );
        assert_eq!(
            nonce_key.to_vec(),
            required_hex(&vector, &vector.nonce_key),
            "{name}"
        );

        let plaintext_hash = blake3::hash(&plaintext);
        assert_eq!(
            plaintext_hash.as_bytes().to_vec(),
            required_hex(&vector, &vector.plaintext_hash),
            "{name}"
        );
        let prefix = vector.cipher().derive_nonce_prefix(&plaintext_hash);
        assert_eq!(
            prefix,
            required_hex(&vector, &vector.nonce_prefix),
            "{name}"
        );

        // Nonce layout: prefix || chunk index (u32 BE) || last flag.
        let chunk_count = plaintext.len().div_ceil(CHUNK_SIZE).max(1) as u32;
        let first_is_last = u8::from(chunk_count == 1);
        let first = [&prefix[..], &0u32.to_be_bytes(), &[first_is_last]].concat();
        let last = [&prefix[..], &(chunk_count - 1).to_be_bytes(), &[1]].concat();
        assert_eq!(
            first,
            required_hex(&vector, &vector.first_chunk_nonce),
            "{name}"
        );
        assert_eq!(
            last,
            required_hex(&vector, &vector.last_chunk_nonce),
            "{name}"
        );
    }
}

#[test]
fn encrypted_blobs_match_vectors() {
    for vector in document().vectors {
        let name = &vector.name;
        let plaintext = vector.plaintext();

        let mut blob = Vec::new();
        let info = encrypt_blob(
            vector.cipher().as_ref(),
            &mut Cursor::new(&plaintext),
            &mut blob,
        )
        .unwrap();

        let header = hex(&vector.header);
        assert_eq!(info.plaintext_len, vector.plaintext_len, "{name}");
        assert_eq!(info.blob_len, vector.blob_len, "{name}");
        assert_eq!(blob.len() as u64, info.blob_len, "{name}");
        assert_eq!(blob[..header.len()], header, "{name}");
        assert_eq!(
            blake3::hash(&blob).as_bytes().to_vec(),
            hex(&vector.blob_hash),
            "{name}"
        );
        if let Some(expected) = &vector.blob {
            assert_eq!(blob, hex(expected), "{name}");
        }
    }
}

#[test]
fn vector_blobs_decrypt_to_plaintext() {
    for vector in document().vectors {
        let Some(blob) = &vector.blob else {
            continue;
        };
        let mut decrypted = Vec::new();
        decrypt_blob(
            vector.cipher().as_ref(),
            &mut Cursor::new(hex(blob)),
            &mut decrypted,
        )
        .unwrap();
        assert_eq!(decrypted, vector.plaintext(), "{}", vector.name);
    }
}
